{
  "items": [
    {
      "name": "Polynomial.natDegree_hasseDeriv_le",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (n : ℕ),\n  ((Polynomial.hasseDeriv n) p).natDegree ≤ p.natDegree - n"
    },
    {
      "name": "MvPolynomial.degreeOf_pow_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (i : σ) (p : MvPolynomial σ R) (n : ℕ),\n  MvPolynomial.degreeOf i (p ^ n) ≤ n * MvPolynomial.degreeOf i p"
    },
    {
      "name": "Polynomial.degree_derivative_lt",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p : Polynomial R}, p ≠ 0 → (Polynomial.derivative p).degree < p.degree"
    },
    {
      "name": "Polynomial.natDegree_derivative_le",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R), (Polynomial.derivative p).natDegree ≤ p.natDegree - 1"
    },
    {
      "name": "MvPolynomial.degreeOf_le_totalDegree",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (f : MvPolynomial σ R) (i : σ),\n  MvPolynomial.degreeOf i f ≤ f.totalDegree"
    },
    {
      "name": "Polynomial.natDegree_det_X_add_C_le",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Polynomial",
      "kind": "theorem",
      "type": "∀ {n : Type u_1} {α : Type u_2} [inst : DecidableEq n] [inst_1 : Fintype n] [inst_2 : CommRing α] (A B : Matrix n n α),\n  (Polynomial.X • A.map ⇑Polynomial.C + B.map ⇑Polynomial.C).det.natDegree ≤ Fintype.card n"
    }
  ]
}
